<script>
import { ChatSearchRequest } from '@/api/model/ChatSearchRequest'

export default {
  name: 'RecentsSection',
  components: {
    ChatSearch: () => import('../chat/ChatSearch.vue'),
    ChatProjectIcon: () => import('../ChatProjectIcon.vue'),
    ChatRecentItem: () => import('../chat/ChatRecentItem.vue')
  },
  props: {
    chats: { type: Array, default: () => [] },
    isCollapsed: { type: Boolean, default: false },
    isLoading: { type: Boolean, default: false },
    activeChatId: { type: String, default: null },
    isMobile: { type: Boolean, default: false }
  },
  emits: ['select-chat', 'scroll-end'],
  data() {
    return {
      recentsExpanded: true,
      isSearchModalOpen: false,
      searchResults: [],
      searchMeta: null,
      searchPerformed: false,
      isSearching: false,
      searchStatus: null,
      visibleChatIds: new Set(),
      unreadCountCache: {},
      chatMessageWatchers: new Map()
    }
  },
  computed: {
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    displayedChats() {
      return this.chats || []
    }
  },
  watch: {
    chats: {
      handler(newChats) {
        if (newChats && newChats.length > 0) {
          this.setupMessageWatchers(newChats)
          this.updateUnreadCountCache()
        }
      },
      deep: true
    }
  },
  mounted() {
    this.updateVisibleChats()
    if (this.chats && this.chats.length > 0) {
      this.setupMessageWatchers(this.chats)
    }
  },
  beforeUnmount() {
    this.cleanupMessageWatchers()
  },
  methods: {
    setupMessageWatchers(chats) {
      chats.forEach(chat => {
        if (!chat?.id) return

        // Only set up watcher if not already watching this chat
        if (!this.chatMessageWatchers.has(chat.id)) {
          const unwatch = this.$watch(
            () => chat.messages,
            () => {
              this.updateUnreadCountCache()
              this.$forceUpdate()
            },
            { deep: true }
          )
          this.chatMessageWatchers.set(chat.id, unwatch)
        }
      })
    },
    cleanupMessageWatchers() {
      this.chatMessageWatchers.forEach(unwatch => {
        if (typeof unwatch === 'function') {
          unwatch()
        }
      })
      this.chatMessageWatchers.clear()
    },
    updateVisibleChats() {
      this.visibleChatIds.clear()

      const openApps = this.$storex?.ui?.openApps || {}
      Object.values(openApps).forEach(app => {
        if (app.tabId) {
          this.visibleChatIds.add(app.tabId)
        }
      })

      try {
        const chatId = this.$storex?.$router?.$navigation?.getChatId?.()
        if (chatId) {
          this.visibleChatIds.add(chatId)
        }
      } catch (error) {
        console.log('Could not get chat ID from router')
      }
    },
    isVisibleChat(chat) {
      return this.visibleChatIds.has(chat.id)
    },
    updateUnreadCountCache() {
      const currentUsername = this.$user?.username
      if (!currentUsername) return

      this.displayedChats.forEach(chat => {
        const count = (chat.messages || []).filter(msg => {
          const isAssistantMsg = msg.role === 'assistant'
          const isOtherUser = msg.user !== currentUsername
          const isUnread = !msg.read_by || !msg.read_by.includes(currentUsername)
          return isAssistantMsg && isOtherUser && isUnread && !msg.hide
        }).length
        this.unreadCountCache[chat.id] = count
      })
    },
    getUnreadCountReactive(chat) {
      return this.unreadCountCache[chat.id] || 0
    },
    openSearchModal() {
      this.isSearchModalOpen = true
    },
    closeSearchModal() {
      this.isSearchModalOpen = false
      this.clearSearch()
    },
    async executeSearch(searchData) {
      this.isSearching = true
      this.searchStatus = null
      this.searchPerformed = true
      this.searchResults = []

      try {
        const searchRequest = new ChatSearchRequest({
          query: searchData.query,
          user_id: this.currentUser?.id,
          from_date: searchData.dateRange?.from_date,
          to_date: searchData.dateRange?.to_date,
          page: searchData.page || 1,
          page_size: searchData.pageSize || 20,
          filters: searchData.filters || {}
        })

        const results = await this.$storex.chats.searchChats(searchRequest)

        if (!results) {
          this.searchStatus = 'No response from server'
          return
        }

        if (results.error) {
          this.searchStatus = `Error: ${results.error}`
          return
        }

        if (results.total === 0) {
          this.searchStatus = 'No results found'
          this.searchResults = []
        } else {
          this.searchStatus = `Found ${results.total} result${results.total !== 1 ? 's' : ''}`
          this.searchResults = results.results || []
          this.searchMeta = {
            total: results.total,
            total_pages: results.total_pages || 1,
            page: searchData.page || 1,
            pageSize: searchData.pageSize || 20
          }
        }
      } catch (error) {
        console.error('Search error:', error)
        this.searchStatus = `Error: ${error.message || 'Search failed'}`
        this.searchResults = []
      } finally {
        this.isSearching = false
      }
    },
    selectSearchResult(result) {
      const chat = result.chat || result
      this.handleSelectChat(chat)
      this.closeSearchModal()
    },
    clearSearch() {
      this.searchResults = []
      this.searchMeta = null
      this.searchPerformed = false
      this.searchStatus = null
      try {
        this.$storex.chats.clearChatSearch?.()
      } catch (e) {
        console.log('Clear search called')
      }
    },
    handleSelectChat(chat) {
      this.$emit('select-chat', chat)
    },
    getInitials(name) {
      if (!name) return 'CH'
      const cleanName = name.replace(/[^\w\s-]/g, '').trim()
      const words = cleanName.split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    isActivChat(chat) {
      return this.activeChatId === chat.id
    },
    handleScroll(e) {
      const { scrollTop, clientHeight, scrollHeight } = e.target
      if (scrollHeight - scrollTop - clientHeight < 100) {
        this.$emit('scroll-end')
      }
    }
  }
}
</script>
